pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let dynamic_factor = if progress < 0.5 { 1.0 } else { 2.0 };
    let decay_penalty = (1.0 - progress).powi(3);
    let open_bins_weight = open_bins_count as f64 / total_items as f64 * 0.5;
    let residual_weight = bin_residual as f64 / mean_residual;

    // Introduce non-linear conditionals and time-decaying penalties
    let penalty_factor = if progress < 0.25 { 1.5 } else if progress < 0.75 { 1.0 } else { 0.5 };
    let decayed_residuum = bin_residual as f64 * decay_penalty;

    // Horizon-aware placement logic
    let step_bonus = (total_items - step_index) as f64 / total_items as f64 * 0.2;
    let open_bins_cost = if open_bins_count > 1 { open_bins_count as f64 * 0.5 } else { 0.0 };

    let score = bin_residual as f64 - item_size as f64 * dynamic_factor * (1.0 + open_bins_count as f64 / total_items as f64)
        - open_bins_weight * step_bonus
        + mean_residual * decayed_residuum
        - open_bins_cost;

    score * (residual_weight + open_bins_weight) / 2.0
}

