pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let dynamic_factor = if progress < 0.5 { 1.0 } else { 2.0 };
    let decay_factor = (total_items - step_index) as f64 / total_items as f64;
    let penalty = (item_size as f64 * dynamic_factor * decay_factor).powi(3);
    let mean_residual_weight = 0.5 * mean_residual * progress.powf(2);
    let additional_penalty = if bin_residual < item_size {
        ((item_size - bin_residual) as f64 / bin_capacity as f64).powi(3)
    } else {
        0.0
    };
    let time_decay_penalty = (1.0 - progress).powi(2);
    let horizon_weight = if step_index < total_items / 2 { progress.powf(3) } else { (1.0 - progress).powf(3) };

    let score = bin_residual as f64
        - ((penalty + mean_residual_weight + additional_penalty + time_decay_penalty)
            / open_bins_count as f64
            * horizon_weight
            * 1.5); // Increased penalty factor to improve compaction

    score
}
